def make(i, row):
    tag, prompt, opts, answer, reason = row
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(opts)]
    aid = next(o['id'] for o in options if o['text'] == answer)
    refs = [{'url': u, 'title': t + '；僅研究題型與能力方向，未複製原題。', 'year': '113-114', 'subject': 'social', 'locator': loc, 'observedPattern': '公開社會科文化資料題研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'} for u, t, loc in SOURCES]
    steps = [f'讀題定位：圈出「{tag}」與題目給的群體、時間、空間、證據或影響指標。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合文化特色及影響的多元資料判讀。', '排除誘答：檢查是否只看單一群體、單次活動、總量或宣傳說法，忽略尺度與資料來源。', '結論回查：確認文化主張的時間、空間與適用範圍，保留仍需互證的部分。']
