for i, row in enumerate(DATA, 1):
    (OUT / f'question-social-content-geo-bg-iv-2-{i}.json').write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + '\n')
print('rewrote', len(DATA), 'questions')
